const tabId = 248688717;

const specs = await browserjs(tabId, () => {
  const title = document.querySelector('h1')?.textContent?.trim();
  const price = document.querySelector('.priceView-customer-price span, [data-testid="customer-price"] span, .priceView-hero-price span')?.textContent?.trim();

  // Find all spec rows
  const specRows = Array.from(document.querySelectorAll('.spec-row, [data-spec-title], tr, .specs-table-row, li')).map(el => {
    const text = el.innerText?.replace(/\s+/g, ' ').trim();
    return text;
  }).filter(t => t && (
    t.toLowerCase().includes('screen size') ||
    t.toLowerCase().includes('refresh rate') ||
    t.toLowerCase().includes('panel type') ||
    t.toLowerCase().includes('display type') ||
    t.toLowerCase().includes('qled') ||
    t.toLowerCase().includes('resolution')
  ));

  // Also search the entire page text for QLED, 240Hz, 49"
  const bodyText = document.body.innerText;
  const matches = {
    hasQLED: /QLED/i.test(bodyText),
    has240Hz: /240\s*Hz/i.test(bodyText),
    has49: /49\s*(\"|inch)/i.test(bodyText)
  };

  return {
    title,
    price,
    specRows: specRows.slice(0, 20),
    matches
  };
});

console.log("Specs:", JSON.stringify(specs, null, 2));

